    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.68.0/ankra-cli-linux-arm64"
      sha256 "ad2c9fc2ed1ff76ceb3bf995eb083c10e870227acc0bff7030d6f87589e120d1"
